create extension if not exists pgcrypto;
create schema if not exists private;
do $$ begin create type public.app_role as enum ('student','parent','teacher','admin','cafeteria'); exception when duplicate_object then null; end $$;
do $$ begin create type public.payment_status as enum ('pending','succeeded','failed','expired'); exception when duplicate_object then null; end $$;
do $$ begin create type public.order_status as enum ('pending','paid','preparing','ready','completed','cancelled'); exception when duplicate_object then null; end $$;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',role public.app_role not null default 'student',student_code text unique,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.classes(id uuid primary key default gen_random_uuid(),name text not null,school_year text not null default '2026-2027');
create table if not exists public.class_members(class_id uuid references public.classes(id) on delete cascade,student_id uuid references public.profiles(id) on delete cascade,primary key(class_id,student_id));
create table if not exists public.subjects(id uuid primary key default gen_random_uuid(),name text not null,coefficient numeric(5,2) not null default 1);
create table if not exists public.grades(id uuid primary key default gen_random_uuid(),student_id uuid references public.profiles(id) on delete cascade not null,subject_id uuid references public.subjects(id) on delete cascade not null,value numeric(5,2) not null check(value>=0 and value<=20),term text not null default 'T1',created_at timestamptz not null default now());
create table if not exists public.schedule(id uuid primary key default gen_random_uuid(),class_id uuid references public.classes(id) on delete cascade,subject_id uuid references public.subjects(id),teacher_id uuid references public.profiles(id),room text not null,weekday smallint not null check(weekday between 1 and 7),starts_at time not null,ends_at time not null);
create table if not exists public.food_items(id text primary key,name text not null,price_xof integer not null check(price_xof>0),active boolean not null default true);
create table if not exists public.food_orders(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) not null,total_xof integer not null,status public.order_status not null default 'pending',pickup_date date,pickup_slot text,wave_checkout_id text unique,wave_transaction_id text unique,created_at timestamptz not null default now());
create table if not exists public.food_order_items(id uuid primary key default gen_random_uuid(),order_id uuid references public.food_orders(id) on delete cascade not null,food_item_id text references public.food_items(id) not null,quantity integer not null check(quantity>0),unit_price_xof integer not null);
create table if not exists public.school_payments(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) not null,description text not null,amount_xof integer not null,status public.payment_status not null default 'pending',due_date date,wave_checkout_id text unique,wave_transaction_id text unique,created_at timestamptz not null default now());
create table if not exists public.point_ledger(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) on delete cascade not null,points integer not null,reason text not null,created_at timestamptz not null default now());
create table if not exists public.rewards(id uuid primary key default gen_random_uuid(),name text not null,points_cost integer not null check(points_cost>0),active boolean not null default true);
create table if not exists public.reward_redemptions(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) not null,reward_id uuid references public.rewards(id) not null,points_spent integer not null,created_at timestamptz not null default now());
create table if not exists public.wave_events(id text primary key,event_type text not null,payload jsonb not null,received_at timestamptz not null default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,role) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),'student') on conflict(id) do nothing; return new; end $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function private.is_staff() returns boolean language sql security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role in ('admin','teacher','cafeteria')); $$;
revoke all on function private.is_staff() from public; grant execute on function private.is_staff() to authenticated;
alter table public.profiles enable row level security;alter table public.classes enable row level security;alter table public.class_members enable row level security;alter table public.subjects enable row level security;alter table public.grades enable row level security;alter table public.schedule enable row level security;alter table public.food_items enable row level security;alter table public.food_orders enable row level security;alter table public.food_order_items enable row level security;alter table public.school_payments enable row level security;alter table public.point_ledger enable row level security;alter table public.rewards enable row level security;alter table public.reward_redemptions enable row level security;alter table public.wave_events enable row level security;
create policy profiles_self on public.profiles for select to authenticated using(id=auth.uid() or (select private.is_staff()));create policy profiles_staff_update on public.profiles for update to authenticated using((select private.is_staff())) with check((select private.is_staff()));create policy classes_read on public.classes for select to authenticated using(true);create policy members_self on public.class_members for select to authenticated using(student_id=auth.uid() or (select private.is_staff()));create policy subjects_read on public.subjects for select to authenticated using(true);create policy grades_self on public.grades for select to authenticated using(student_id=auth.uid() or (select private.is_staff()));create policy schedule_read on public.schedule for select to authenticated using(true);create policy food_read on public.food_items for select to authenticated using(active=true or (select private.is_staff()));create policy orders_self on public.food_orders for select to authenticated using(user_id=auth.uid() or (select private.is_staff()));create policy orders_insert on public.food_orders for insert to authenticated with check(user_id=auth.uid());create policy order_items_self on public.food_order_items for select to authenticated using(exists(select 1 from public.food_orders o where o.id=order_id and (o.user_id=auth.uid() or (select private.is_staff()))));create policy payments_self on public.school_payments for select to authenticated using(user_id=auth.uid() or (select private.is_staff()));create policy points_self on public.point_ledger for select to authenticated using(user_id=auth.uid() or (select private.is_staff()));create policy rewards_read on public.rewards for select to authenticated using(active=true or (select private.is_staff()));create policy redemption_self on public.reward_redemptions for select to authenticated using(user_id=auth.uid() or (select private.is_staff()));create policy redemption_insert on public.reward_redemptions for insert to authenticated with check(user_id=auth.uid());create policy wave_events_staff on public.wave_events for select to authenticated using((select private.is_staff()));
insert into public.food_items(id,name,price_xof) values ('burger','Burger maison',1500),('sandwich','Sandwich poulet',1000),('pizza','Mini pizza',2000),('drink','Boisson',500) on conflict(id) do update set name=excluded.name,price_xof=excluded.price_xof;
insert into public.rewards(name,points_cost) select * from (values ('Boisson offerte',500),('Menu étudiant',1200),('Carte cadeau 5 000 F',3000)) v(name,points_cost) where not exists(select 1 from public.rewards r where r.name=v.name);
